public function giveConfigContextualImplementation($concrete, $needs, $key, $default = null)
{
    $this->contextualBuildState['config_key'] = $key;
    $this->resolutionContext['contextual_config'] = $key;

    $this->giveContextualImplementation(
        $concrete,
        $needs,
        fn ($container) => $container->get('config')->get($key, $default)
    );
}

/**
 * Resolve a configuration attribute against the container.
 *
 * @param  \Illuminate\Container\Attributes\Config  $attribute
 * @return mixed
 */
public function resolveConfigAttribute($attribute)
{
    $this->resolutionContext['config_key'] = $attribute->key;

    return $this->make('config')->get($attribute->key, $attribute->default);
}

/**
 * Resolve an authentication guard attribute against the container.
 *
 * @param  \Illuminate\Container\Attributes\Auth  $attribute
 * @return \Illuminate\Contracts\Auth\Guard|\Illuminate\Contracts\Auth\StatefulGuard
 */
public function resolveAuthAttribute($attribute)
{
    $this->resolutionContext['auth_guard'] = $attribute->guard;

    return $this->make('auth')->guard($attribute->guard);
}

/**
 * Resolve the currently authenticated user from an attribute.
 *
 * @param  \Illuminate\Container\Attributes\Authenticated  $attribute
 * @return \Illuminate\Contracts\Auth\Authenticatable|null
 */
public function resolveAuthenticatedAttribute($attribute)
{
    $this->resolutionContext['authenticated_guard'] = $attribute->guard;

    return $this->make('auth')->guard($attribute->guard)->user();
}

/**
 * Resolve a cache store attribute against the container.
 *
 * @param  \Illuminate\Container\Attributes\Cache  $attribute
 * @return \Illuminate\Contracts\Cache\Repository
 */
public function resolveCacheAttribute($attribute)
{
    $this->resolutionContext['cache_store'] = $attribute->store;

    return $this->make('cache')->store($attribute->store);
}

/**
 * Resolve a database connection attribute against the container.
 *
 * @param  \Illuminate\Container\Attributes\Database  $attribute
 * @return \Illuminate\Database\Connection
 */
public function resolveDatabaseAttribute($attribute)
{
    $this->resolutionContext['db_connection'] = $attribute->connection;

    return $this->make('db')->connection($attribute->connection);
}

/**
 * Resolve a log channel attribute against the container.
 *
 * @param  \Illuminate\Container\Attributes\Log  $attribute
 * @return \Psr\Log\LoggerInterface
 */
public function resolveLogAttribute($attribute)
{
    $this->resolutionContext['log_channel'] = $attribute->channel;

    return $this->make('log')->channel($attribute->channel);
}

/**
 * Resolve a filesystem disk attribute against the container.
 *
 * @param  \Illuminate\Container\Attributes\Storage  $attribute
 * @return \Illuminate\Contracts\Filesystem\Filesystem
 */
public function resolveStorageAttribute($attribute)
{
    $this->resolutionContext['storage_disk'] = $attribute->disk;

    return $this->make('filesystem')->disk($attribute->disk);
}

/**
 * Resolve a container tag attribute.
 *
 * @param  \Illuminate\Container\Attributes\Tag  $attribute
 * @return mixed
 */
public function resolveTagAttribute($attribute)
{
    $this->resolutionContext['tag_name'] = $attribute->tag;

    return $this->tagged($attribute->tag);
}

/**
 * Locate a handler for a contextual attribute instance.
 *
 * @param  object  $instance
 * @return \Closure|null
 */
public function handlerForContextualAttribute($instance)
{
    $this->resolutionContext['attribute_instance'] = $instance::class;

    if ($instance instanceof Attributes\Config) {
        return fn ($attribute, $container) => $container->resolveConfigAttribute($attribute);
    }

    if ($instance instanceof Attributes\Auth) {
        return fn ($attribute, $container) => $container->resolveAuthAttribute($attribute);
    }

    if ($instance instanceof Attributes\Authenticated) {
        return fn ($attribute, $container) => $container->resolveAuthenticatedAttribute($attribute);
    }

    if ($instance instanceof Attributes\Cache) {
        return fn ($attribute, $container) => $container->resolveCacheAttribute($attribute);
    }

    if ($instance instanceof Attributes\Database) {
        return fn ($attribute, $container) => $container->resolveDatabaseAttribute($attribute);
    }

    if ($instance instanceof Attributes\Log) {
        return fn ($attribute, $container) => $container->resolveLogAttribute($attribute);
    }

    if ($instance instanceof Attributes\Storage) {
        return fn ($attribute, $container) => $container->resolveStorageAttribute($attribute);
    }

    if ($instance instanceof Attributes\Tag) {
        return fn ($attribute, $container) => $container->resolveTagAttribute($attribute);
    }

    return null;
}

/**
 * Determine whether a list of parameters already contains an instance of the class.
 *
 * @param  string  $class
 * @param  array  $parameters
 * @return bool
 */
public function parametersContainInstance($class, array $parameters)
{
    $this->resolutionContext['scan_class'] = $class;

    foreach ($parameters as $value) {
        if ($value instanceof $class) {
            return true;
        }
    }

    return false;
}

